window.LD=window.LD||{};window.LD["party/p6"]={"id":"p6","name":"The Coin of Thornwall","poss":"The Coin of Thornwall's","members":["h1","h8","h16"],"leader":"h1","morale":100,"disposition":"wary","motto":"Double or nothing.","banner":{"c1":"#e8c83a","c2":"#7a4cc8","emblem":"coin"},"loc":"saltmarrow","loc_name":"Saltmarrow","goal":{"text":"to earn 400 silver between them before the season ends","kind":"purse","done":90,"progress":"435 silver, past the 400 aimed for","missed":false,"crew":"The Coin of Thornwall","party":"p6"},"vows":[{"text":"to share every coin","day":31,"state":"broken","ended":63,"through":false,"progress":"broken on day 3 of season 3","crew":"The Coin of Thornwall","party":"p6"}],"doing":"last seen heading back to Veldrock","progress":null,"today":["XP: Brix +987 (level 22!), Hazel +800, Tamsin +823.","Coin between them: +56 silver.","Came away with a healing potion.","Sold 7 sea grapes, 7 fangs & claws, 5 fish, 2 cliff crab claws, 2 herbs, a bog crawler claw, a drake scale, a barnacle oyster."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":277,"season":{"wins":12,"bosses":0,"floors":6,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":4},"career":{"wins":34,"bosses":2,"floors":18,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":11},"former":[],"fallen":[],"travel":null,"wagon":null,"pace_gap":18,"rels":[{"party":"p1","score":100},{"party":"p7","score":100},{"party":"p2","score":50},{"party":"p3","score":34},{"party":"p4","score":32},{"party":"p5","score":14}],"events":[{"id":"e791","day":21,"season":1,"sday":21,"kind":"night","imp":2,"text":"Something small and clever gets into The Coin of Thornwall's camp in Bleakmarsh overnight. Hazel wakes up 5 silver and 1 ration lighter.","heroes":["h1","h8"],"parties":["p6"],"loc":"bleakmarsh"},{"id":"e823","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"Hazel once called Brix's singing a crime. Tonight Hazel asks for another verse.","heroes":["h8","h1"],"parties":["p6"],"loc":"bleakmarsh"},{"id":"e850","day":22,"season":1,"sday":22,"kind":"fight","imp":1,"text":"The Coin of Thornwall meets Risen Dead in Bleakmarsh and beats it. Hazel's Bone Spear took most of the fight out of the risen dead in one go. Hazel kept them off everyone with Raise Skeleton. Loot: 2 remains, 3 crypt-caps.","heroes":["h1","h8"],"parties":["p6"],"loc":"bleakmarsh","fight":"f75","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-13},{"id":"e860","day":22,"season":1,"sday":22,"kind":"party_join","imp":3,"text":"Tamsin joins The Coin of Thornwall around the campfire in Bleakmarsh. That makes 3.","heroes":["h16","h1","h8"],"parties":["p6"],"loc":"bleakmarsh"},{"id":"e882","day":22,"season":1,"sday":22,"kind":"goal_done","imp":4,"text":"GOAL: The Coin of Thornwall set out to earn 200 silver between them before the season ends, and they have done it, with 8 days to spare. XP: Brix +960 (level 12!), Hazel +960 (level 12!), Tamsin +960 (level 10!).","heroes":["h1","h8","h16"],"parties":["p6"],"xp":{"h1":960,"h8":960,"h16":960}},{"id":"e908","day":23,"season":1,"sday":23,"kind":"fight","imp":3,"text":"Hazel hits hardest as the Coin of Thornwall makes short work of 3 Giant Spiders and 2 Bog Crawlers in Bleakmarsh. Hazel had the last word, and the word was Drain Life. Loot: 7 chitin, 4 spider legs.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"bleakmarsh","fight":"f78","foes":["bog_crawler","giant_spider","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-22},{"id":"e909","day":23,"season":1,"sday":23,"kind":"ability","imp":2,"text":"The fight in Bleakmarsh is barely over and Tamsin is drawing it in the dirt with a stick: who stood where, what worked, what nearly didn't. Brix and the rest learn more than the fight itself taught them.","heroes":["h16","h1"],"parties":["p6"],"loc":"bleakmarsh","skill":"born_teacher","sk":"Born Teacher","rule":true},{"id":"e910","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Hazel smokes the day's catch over a slow fire all night. Breakfast is spectacular.","heroes":["h8"],"parties":["p6"],"loc":"bleakmarsh","skill":"smokehouse"},{"id":"e920","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Tamsin turns the whole day's walk into a quiz. Hazel wins the last round. That's Born Teacher for you.","heroes":["h16","h8"],"parties":["p6"],"loc":"bleakmarsh","skill":"born_teacher"},{"id":"e926","day":23,"season":1,"sday":23,"kind":"argument","imp":1,"text":"Tamsin and Brix of The Coin of Thornwall have a shouting match about Tamsin's snoring.","heroes":["h16","h1"],"parties":["p6"]},{"id":"e958","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Tamsin spends an afternoon teaching Carrbridge's apprentices to tie proper knots. Somebody asks how. 'Born Teacher,' says Tamsin.","heroes":["h16"],"parties":["p6"],"loc":"carrbridge","skill":"born_teacher","wx":"rain"},{"id":"e986","day":25,"season":1,"sday":25,"kind":"party_life","imp":3,"text":"By the third crossroads Hazel has stopped waiting and started complaining about the wait.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"carrbridge","wx":"rain"},{"id":"e987","day":25,"season":1,"sday":25,"kind":"road","imp":3,"text":"Brix turns Lady Perpetua Vane the right way round at last and walks her until the towers come into sight. She calls it 'a pleasant coincidence'.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"carrbridge~thornwall","traveller":"perpetua","road_rec":"r172"},{"id":"e1028","day":26,"season":1,"sday":26,"kind":"bond","imp":3,"text":"The Coin of Thornwall and The Thunder of Frosthold are rivals now, starting with Brix and Pickles.","heroes":["h1","h4"],"parties":["p6","p3"],"bond":"rivals"},{"id":"e1032","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Hazel has an old skeleton point the party down the right corridor. It does a little bow afterwards.","heroes":["h8"],"parties":["p6"],"loc":"goblin_camp","skill":"make_them_wave"},{"id":"e1043","day":27,"season":1,"sday":27,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into Goblin Camp, untouched (0%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","wx":"storm"},{"id":"e1044","day":27,"season":1,"sday":27,"kind":"fight","imp":1,"text":"In the guard hut on floor 1 of Goblin Camp, the Coin of Thornwall dispatches 3 Goblins. One Pounce from Tamsin, and the goblin stopped being a problem. Loot: 3 silver each, 3 goblin ears.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","fight":"f83","foes":["goblin","goblin","goblin"],"where":"in the guard hut on floor 1 of Goblin Camp","won":true,"close":false,"shape":"place","reworded":-1,"wx":"storm"},{"id":"e1046","day":27,"season":1,"sday":27,"kind":"ability","imp":2,"text":"Tamsin makes the partymates replay the fight in Goblin Camp at walking pace, like a dance lesson. Everybody feels silly. Everybody gets better.","heroes":["h16"],"parties":["p6"],"loc":"goblin_camp","skill":"born_teacher","sk":"Born Teacher","rule":true,"wx":"storm"},{"id":"e1047","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 1 of Goblin Camp at a steady pace: 4 rooms (the fence-post wall, the guard hut, a hidden room behind the guard hut and 1 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":2,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1077","day":27,"season":1,"sday":27,"kind":"talent","imp":2,"text":"Tamsin shows Brix a better grip. Brix hasn't dropped a weapon since. Tamsin puts it down to Born Teacher.","heroes":["h16","h1"],"parties":["p6"],"loc":"goblin_camp","skill":"born_teacher","wx":"storm"},{"id":"e1095","day":28,"season":1,"sday":28,"kind":"gear","imp":4,"text":"Out of Goblin Camp comes Brix, and with Brix comes a dented bucket with eye-holes punched in it from the Warchief's Bucket: one of a kind, and not yet understood.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp"},{"id":"e1096","day":28,"season":1,"sday":28,"kind":"famous_trap","imp":4,"text":"The Warchief's Bucket, the trap everyone in Goblin Camp talks about, is disarmed at last. Tamsin did it, and kept a piece as proof.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp"},{"id":"e1097","day":28,"season":1,"sday":28,"kind":"fight","imp":3,"text":"The Coin of Thornwall, in fine spirits lately, beats 2 Goblins and a Goblin Archer in the sharpening yard on floor 1 of Goblin Camp. Hazel sent Bone Spear across the fight. The goblin didn't come back from it. Without Tamsin's Wild Shape, this goes differently. Loot: 2 silver each, 3 goblin ears, 2 trinkets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","fight":"f90","foes":["goblin","goblin_archer","goblin"],"where":"in the sharpening yard on floor 1 of Goblin Camp","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1098","day":28,"season":1,"sday":28,"kind":"gear","imp":1,"text":"In the counting room on floor 1 of Goblin Camp, Brix finds a Goblin-Stitched Fine Cloak and puts it on. Goblin-Stitched: a little harder to hit (+1.5 dodge).","heroes":["h1"],"parties":["p6"],"loc":"goblin_camp"},{"id":"e1099","day":28,"season":1,"sday":28,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 1 of Goblin Camp at a push pace: 5 rooms (The Warchief's Bucket, the boot pile, the sharpening yard and 2 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","pace":"push","stats":{"rooms":5,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique","great"],"fears":2,"wild":[]}},{"id":"e1110","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Tamsin lies back and names constellations for Hazel. Some of them are even real.","heroes":["h16","h8"],"parties":["p6"],"loc":"goblin_camp","skill":"stargazer"},{"id":"e1124","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 1 of Goblin Camp at a push pace: 4 rooms (an empty sleeping hole, the slop pit, a hidden room behind the slop pit and 1 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","pace":"push","stats":{"rooms":4,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":1,"wild":[]}},{"id":"e1176","day":30,"season":1,"sday":30,"kind":"wild_room","imp":3,"text":"Tamsin's coin has still never landed wrong. It landed on its edge once, which Tamsin says doesn't count.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","room":"wild_heads_or_tails"},{"id":"e1177","day":30,"season":1,"sday":30,"kind":"fight","imp":2,"text":"Three Goblins, a Goblin Archer and a Goblin Shaman learn the hard way not to bother the Coin of Thornwall in the chief's hall on floor 1 of Goblin Camp. Brix called Hold the Line, and the line steadied. Loot: 5 silver each, 9 goblin ears, 3 herbs.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","fight":"f92","foes":["goblin_archer","goblin","goblin_shaman"],"where":"in the chief's hall on floor 1 of Goblin Camp","won":true,"close":false,"shape":"foe","reworded":-29},{"id":"e1178","day":30,"season":1,"sday":30,"kind":"ability","imp":2,"text":"After the win in Goblin Camp, Tamsin walks the crew back through it step by step, kindly. Everyone takes something away for next time.","heroes":["h16"],"parties":["p6"],"loc":"goblin_camp","skill":"born_teacher","sk":"Born Teacher","rule":true},{"id":"e1179","day":30,"season":1,"sday":30,"kind":"fight","imp":1,"text":"The Coin of Thornwall runs into 3 Goblins in the burrow junction on floor 1 of Goblin Camp and comes out on top. Brix's War Chant had everyone hitting harder. Without Hazel's Raise Skeleton, this goes differently. Loot: 3 silver each, 5 goblin ears, 1 trinket.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","fight":"f93","foes":["goblin","goblin","goblin"],"where":"in the burrow junction on floor 1 of Goblin Camp","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e1181","day":30,"season":1,"sday":30,"kind":"skim","imp":3,"text":"13 silver goes missing from The Coin of Thornwall's haul. Hazel finds it in Brix's boot.","heroes":["h8","h1"],"parties":["p6"],"loc":"goblin_camp","in_fight":"f94"},{"id":"e1182","day":30,"season":1,"sday":30,"kind":"boss","imp":5,"text":"Hazel hits hardest while the Coin of Thornwall puts an end to Gruk the Warchief's Heir, a Goblin and a Goblin Shaman at the bottom of Goblin Camp. Hazel closed it out with Drain Life on it. Brix's Hold the Line came at the right time for all of them. Ask the others what won it: Tamsin's Wild Shape. Without Hazel's Raise Skeleton, this goes differently. Loot: 16 silver each, 7 goblin ears, 3 trinkets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","fight":"f94","foes":["goblin_warchief","goblin","goblin_shaman"],"where":"at the bottom of Goblin Camp","won":true,"close":false,"shape":"hero","reworded":-12},{"id":"e1183","day":30,"season":1,"sday":30,"kind":"treasure","imp":2,"text":"The hoard Gruk the Warchief's Heir died defending comes to 6 gold pieces and 8 silver. It leaves in every pocket available.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","in_fight":"f94"},{"id":"e1184","day":30,"season":1,"sday":30,"kind":"gear","imp":3,"text":"In the warchief's hole on floor 1 of Goblin Camp, Tamsin finds Warchief's Ranger's Leathers and puts them on. Goblin-Stitched: a little harder to hit (+1.5 dodge). It is a step up from anything Tamsin could buy.","heroes":["h16"],"parties":["p6"],"loc":"goblin_camp"},{"id":"e1185","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 1 of Goblin Camp at a push pace: 4 rooms (the two plaques, the chief's hall, the burrow junction and 1 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","pace":"push","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":0,"gear":["common","great"],"fears":3,"wild":["wild_heads_or_tails"]}},{"id":"e1186","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"After 4 days underground, The Coin of Thornwall climbs back into the open air, gulping it down like water. They inked 94% of the map, reached the deepest floor, found a hidden room behind the guard hut, The Warchief's Bucket, the counting room and 3 more good rooms, cleared 17 rooms, took the teeth out of 4 traps and came away with 268 silver between them. Add up every party's sketches and Goblin Camp comes out mostly explored (78%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"goblin_camp","days":4,"bottom":true,"rooms":["a hidden room behind the guard hut","The Warchief's Bucket"],"gold":268,"turn":"done"},{"id":"e1187","day":30,"season":1,"sday":30,"kind":"talent","imp":2,"text":"Hazel talks for an hour about a brother back home. Tamsin just listens, which turns out to be the whole job. (Good Listener, if anyone's asking.)","heroes":["h16","h8"],"parties":["p6"],"loc":"goblin_camp","skill":"good_listener"},{"id":"e1194","day":30,"season":1,"sday":30,"kind":"song","imp":3,"text":"A travelling bard at The Sagging Beam has a new song: \"The Coward's Jig\". Every verse is about what Brix did in Goblin Camp. The chorus is already stuck in everyone's head.","heroes":["h1"],"parties":["p6"],"loc":"thornwall","song":"s30_18"},{"id":"e1200","day":30,"season":1,"sday":30,"kind":"tarot","imp":2,"text":"Nobody sleeps until Hazel has read for The Coin of Thornwall. The night before Goblin Camp, three cards: the Chariot, the Ten of Cups and the Ace of Cups. Hazel smiles at the last card.","heroes":["h1","h8"],"parties":["p6"],"loc":"goblin_camp","reading":"r204"},{"id":"e1209","day":30,"season":1,"sday":30,"kind":"big_move","imp":4,"text":"Hazel hits hardest while the Coin of Thornwall puts an end to Gruk the Warchief's Heir, a Goblin and a Goblin Shaman at the bottom of Goblin Camp. On the table: Tamsin +69 renown (19th to 13th), Hazel +69 (16th to 8th) and Brix +68 (11th to 4th). The Coin of Thornwall +130 party renown (5th to 4th among the crews).","heroes":["h16","h8","h1"],"parties":["p6"],"cause":"e1182","moves":[{"hero":"h16","gain":69,"from":19,"to":13},{"hero":"h8","gain":69,"from":16,"to":8},{"hero":"h1","gain":68,"from":11,"to":4}],"party_moves":[{"party":"p6","gain":130,"from":5,"to":4}],"fight":"f94"},{"id":"e1235","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"Philippa Fisk asks Brix to settle a bet about trolls and bridges. Brix settles it, and a fair few other bets while they are at it.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"ironhaven~veldrock","traveller":"truant_scholars","road_rec":"r207"},{"id":"e1241","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"Two crews, one boss. The Thunder of Frosthold and The Coin of Thornwall have both set out for Thornmere Ruins. The taverns are taking bets.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins"},{"id":"e1257","day":31,"season":2,"sday":1,"kind":"argument","imp":2,"text":"It starts with whether the last fight was a retreat or a 'tactical repositioning'. It ends with Tamsin and Brix sleeping on opposite sides of the fire.","heroes":["h16","h1"],"parties":["p6"]},{"id":"e1259","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Thirty days in The Coin of Thornwall. Brix and Hazel have stopped keeping score of who owes whom.","heroes":["h1","h8"],"parties":["p6"],"loc":"veldrock"},{"id":"e1267","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"\"We swear it,\" says every member of The Coin of Thornwall: to share every coin. Witnessed, written down, and already being bet against.","heroes":["h1","h8","h16"],"parties":["p6"]},{"id":"e1290","day":32,"season":2,"sday":2,"kind":"argument","imp":4,"text":"Enough is enough: Brix tells Tamsin exactly what everyone in The Coin of Thornwall has been thinking. Nobody sleeps.","heroes":["h16","h1"],"parties":["p6"]},{"id":"e1296","day":33,"season":2,"sday":3,"kind":"road","imp":3,"text":"Teodor sings half of a song and looks at Hazel. Hazel knows the other half. They finish it together, and the road goes quiet in a nice way.","heroes":["h8","h1","h16"],"parties":["p6"],"road":"carrbridge~ironhaven","traveller":"teodor","road_rec":"r227"},{"id":"e1319","day":33,"season":2,"sday":3,"kind":"bar_fight","imp":5,"text":"BAR FIGHT at The Honest Toll! It starts when Brix insists the last round was already paid for, and within a minute Brix, Duren and Morwen are all in it. When the dust settles Brix is still swinging at nobody in particular, and Morwen is in the rain barrel. Jolly Mott bills Brix 15 silver for the furniture and bans them for three nights.","heroes":["h1","h3","h5"],"parties":["p6","p3"],"loc":"carrbridge"},{"id":"e1320","day":33,"season":2,"sday":3,"kind":"song","imp":3,"text":"\"The Ballad of Brix\" is new at The Honest Toll tonight. The song is about a tavern brawl in Carrbridge, more or less. By the third verse the whole room knows the words.","heroes":["h1"],"parties":["p6","p3"],"loc":"carrbridge","song":"s33_19"},{"id":"e1351","day":34,"season":2,"sday":4,"kind":"party_life","imp":1,"text":"Hazel waits at every crossroads for Brix and Tamsin to catch up, and says nothing very loudly.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"carrbridge"},{"id":"e1356","day":34,"season":2,"sday":4,"kind":"rescue","imp":4,"text":"The Scarlet Thorns are in a bad way in Bleakmarsh when The Coin of Thornwall turns up. Brix (Griffin's hero) gets Tobias (Alex's hero) on a horse. A debt is remembered.","heroes":["h1","h6","h8","h16","h9"],"parties":["p6","p1"],"loc":"bleakmarsh","rescuers":["h1","h8","h16"],"wx":"rain"},{"id":"e1361","day":34,"season":2,"sday":4,"kind":"journey","imp":2,"text":"On the way to Bleakmarsh, The Thunder of Frosthold catches up with The Coin of Thornwall. The conversation turns to the best way to cook a rat and never recovers.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"]},{"id":"e1365","day":34,"season":2,"sday":4,"kind":"talent","imp":2,"text":"The crew walks behind Hazel's pack and smells faintly of ham. Tamsin has stopped complaining. Smokehouse, cast gently, for once.","heroes":["h8","h16"],"parties":["p6"],"loc":"bleakmarsh","skill":"smokehouse","wx":"rain"},{"id":"e1389","day":35,"season":2,"sday":5,"kind":"party_life","imp":1,"text":"Brix and Tamsin ask Hazel if the view is nice up there. It is.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1390","day":35,"season":2,"sday":5,"kind":"ambush","imp":2,"text":"On the road to Thornmere Ruins, the Coin of Thornwall dispatches 3 Bounty Hunters and the Bounty Hunters' Captain, sent for the price on Brix's head. Tamsin found the bounty hunter with Pounce and nearly split it in two. Hazel's Make Them Wave turned the fight. Brix kept the bleeding to a minimum. \"Check its pockets,\" says Brix. Loot: 38 silver each, 8 stolen goods, 2 bandit sausages.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"bleakmarsh","fight":"f106","foes":["bandit_captain","bandit","bandit"],"where":"on the road to Thornmere Ruins, sent for the price on Brix's head","won":true,"close":false,"shape":"hunted","reworded":-1,"wx":"rain"},{"id":"e1407","day":35,"season":2,"sday":5,"kind":"meet","imp":2,"text":"The Coin of Thornwall spots The Thunder of Frosthold in Thornmere Ruins and takes the long way round. Half a day lost. Worth it.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1430","day":36,"season":2,"sday":6,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into Thornmere Ruins, partly explored (40%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1431","day":36,"season":2,"sday":6,"kind":"fight","imp":1,"text":"In the refectory on floor 2 of Thornmere Ruins, the Coin of Thornwall beats a Swamp Troll. Hazel's Raise Skeleton put an extra body on the right side of the fight. Loot: 9 silver each, 1 troll hide, 6 herbs.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f110","foes":["swamp_troll"],"where":"in the refectory on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-1,"wx":"rain"},{"id":"e1432","day":36,"season":2,"sday":6,"kind":"ability","imp":2,"text":"Tamsin asks the party three gentle questions about the fight in Thornmere Ruins. By the third, they've all worked out what they'd do better. Hazel writes it down.","heroes":["h16","h8"],"parties":["p6"],"loc":"thornmere_ruins","skill":"born_teacher","sk":"Born Teacher","rule":true,"wx":"rain"},{"id":"e1433","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of Thornmere Ruins at a cautious pace: 2 rooms (the refectory, the pipe organ).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1434","day":36,"season":2,"sday":6,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1437","day":36,"season":2,"sday":6,"kind":"talent","imp":1,"text":"Tamsin stops to point out a trap's tell-tale signs, slowly, so everyone will remember.","heroes":["h16"],"parties":["p6"],"loc":"thornmere_ruins","skill":"born_teacher","wx":"rain"},{"id":"e1447","day":36,"season":2,"sday":6,"kind":"campfire","imp":2,"text":"A fortnight in The Coin of Thornwall, and Hazel now saves Tamsin the dry side of the tent without being asked.","heroes":["h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1448","day":36,"season":2,"sday":6,"kind":"campfire","imp":1,"text":"Tamsin reads aloud while Hazel sharpens blades, and neither wants the chapter to end.","heroes":["h16","h8"],"parties":["p6"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1467","day":37,"season":2,"sday":7,"kind":"fight","imp":2,"text":"It's 3 Bog Crawlers and 2 Sirens against the Coin of Thornwall in the pond banks on floor 2 of Thornmere Ruins, and it isn't close. Hazel put everything into one Soul Reap, and the bog crawler reeled. Loot: 6 chitin, 2 trinkets, 2 bog crawler claws.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f115","foes":["siren","bog_crawler","siren"],"where":"in the pond banks on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-24,"wx":"rain"},{"id":"e1468","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of Thornmere Ruins at a cautious pace: 3 rooms (the font that still fills, the pond banks, the physic garden).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1471","day":37,"season":2,"sday":7,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold end up at the same fire in Thornmere Ruins. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1472","day":37,"season":2,"sday":7,"kind":"talent","imp":2,"text":"Brix measures every doorway on the floor with their shield. Most are exactly the right size. Hold the Doorway, the guild calls it.","heroes":["h1"],"parties":["p6"],"loc":"thornmere_ruins","skill":"hold_the_doorway","wx":"rain"},{"id":"e1473","day":37,"season":2,"sday":7,"kind":"talent","imp":1,"text":"Tamsin shouts something in Goblin at Thornmere Ruins. The goblins stop, baffled, long enough for the crew to slip by.","heroes":["h16"],"parties":["p6"],"loc":"thornmere_ruins","skill":"linguist","wx":"rain"},{"id":"e1480","day":38,"season":2,"sday":8,"kind":"wild_room","imp":3,"text":"Tamsin's coin has still never landed wrong. It landed on its edge once, which Tamsin says doesn't count.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","room":"wild_heads_or_tails","wx":"storm"},{"id":"e1481","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of Thornmere Ruins at a cautious pace: 3 rooms (the eel-traps, the two plaques, a worn spiral down from the choir, going under the water).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":3,"floor":2,"traps":2,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_heads_or_tails"]},"wx":"storm"},{"id":"e1497","day":38,"season":2,"sday":8,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall camp within sight of each other in Thornmere Ruins and spend the night pretending not to watch.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1502","day":38,"season":2,"sday":8,"kind":"argument","imp":2,"text":"Brix and Tamsin are not speaking. It's about Brix's habit of humming during ambushes. It's never really about Brix's habit of humming during ambushes.","heroes":["h1","h16"],"parties":["p6"]},{"id":"e1517","day":39,"season":2,"sday":9,"kind":"gear","imp":1,"text":"In the hag's still room on floor 3 of Thornmere Ruins, Tamsin finds a Quick Clay Bead Necklace and puts it on. Quicker (+0.8 speed).","heroes":["h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1518","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of Thornmere Ruins at a steady pace: 4 rooms (the cloister garth, the hag's still room, the chapel of the first abbot and 1 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1529","day":39,"season":2,"sday":9,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall end up at the same fire in Thornmere Ruins. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1533","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Hazel practises a very small wave with a very small mouse skeleton. Brix asks her to stop. She doesn't.","heroes":["h8","h1"],"parties":["p6"],"loc":"thornmere_ruins","skill":"make_them_wave","wx":"storm"},{"id":"e1542","day":40,"season":2,"sday":10,"kind":"fight","imp":3,"text":"Brix takes the worst of it as the Coin of Thornwall cuts down 3 Sirens and a Will-o'-Wisp in the reed stair on floor 3 of Thornmere Ruins. Brix's Hold the Line had everyone hitting harder. Raise Skeleton, from Hazel, at exactly the right moment. Loot: 2 trinkets, 7 sea grapes, 1 gem.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f124","foes":["siren","siren","wisp"],"where":"in the reed stair on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-30,"wx":"storm"},{"id":"e1543","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"On the way out of Thornmere Ruins, Tamsin asks Brix what went wrong. Brix says 'nothing'. Tamsin gently disagrees, with examples, and Brix comes away a better fighter.","heroes":["h16","h1"],"parties":["p6"],"loc":"thornmere_ruins","skill":"born_teacher","sk":"Born Teacher","rule":true,"wx":"storm"},{"id":"e1544","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of Thornmere Ruins at a steady pace: 3 rooms (the gallery of charms, the confession box, the reed stair).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1545","day":40,"season":2,"sday":10,"kind":"night","imp":2,"text":"Someone leaves a scrap of map by The Coin of Thornwall's fire on floor 3 of Thornmere Ruins in the night. It shows a door in the Ashveil Crypts that isn't on any other map.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1561","day":40,"season":2,"sday":10,"kind":"meet","imp":1,"text":"The Thunder of Frosthold and The Coin of Thornwall cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1585","day":41,"season":2,"sday":11,"kind":"boss","imp":5,"text":"The Coin of Thornwall slays Mother Thornmere, a Swamp Troll and a Siren at the bottom of Thornmere Ruins and lives to tell of it. Hazel's Chill Touch took the strength out of it. It lost a turn to Tamsin's Stampede. Tamsin accounted for 3 of them, mostly with Pounce. Brix kept everyone standing (12 healed). Loot: 226 silver each, 15 moonpetal, 9 bottled wisplight.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f126","foes":["hag_mother","swamp_troll","siren"],"where":"at the bottom of Thornmere Ruins","won":true,"close":true,"shape":"plain","reworded":4,"wx":"storm"},{"id":"e1586","day":41,"season":2,"sday":11,"kind":"treasure","imp":2,"text":"Nobody knew how much Mother Thornmere had put by. The answer is 15 gold pieces and 2 silver, give or take what fell in the cracks.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","in_fight":"f126","wx":"storm"},{"id":"e1587","day":41,"season":2,"sday":11,"kind":"sniped","imp":3,"text":"Word reaches The Thunder of Frosthold on floor 3 of Thornmere Ruins: The Coin of Thornwall killed Mother Thornmere today. Nobody says much. The side passages still need mapping.","heroes":["h5","h3","h4","h15","h1","h8","h16"],"parties":["p3","p6"],"loc":"thornmere_ruins","snipers":["h1","h8","h16"],"where":"inside","boss":"Mother Thornmere","in_fight":"f126","wx":"storm"},{"id":"e1588","day":41,"season":2,"sday":11,"kind":"race_won","imp":1,"text":"The Coin of Thornwall wins the race to Mother Thornmere, ahead of The Thunder of Frosthold. The bets are paid out in Carrbridge before the blood is dry.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","in_fight":"f126","wx":"storm"},{"id":"e1589","day":41,"season":2,"sday":11,"kind":"gear","imp":4,"text":"Out of Thornmere Ruins comes Hazel, and with Hazel comes a knot of hair and reed on a cord from the Hag Mother's nest: one of a kind, and not yet understood.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1590","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of Thornmere Ruins at a steady pace: 1 room (the Hag Mother's nest).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1591","day":41,"season":2,"sday":11,"kind":"delve_done","imp":3,"text":"The Coin of Thornwall comes out after 6 days, and the first thing anyone wants is bread. They worked through 16 rooms, got all the way to the bottom, mapped 30% of it, found the pipe organ, the pond banks, the two plaques and 4 more good rooms and split 1163 silver on the way up. Counting every crew that has been down, Thornmere Ruins is mostly explored (83%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":["the pipe organ","the pond banks"],"gold":1163,"turn":"done","wx":"storm"},{"id":"e1592","day":41,"season":2,"sday":11,"kind":"night","imp":2,"text":"Something small and clever gets into The Coin of Thornwall's camp outside Thornmere Ruins overnight. Brix wakes up 10 silver and 2 rations lighter.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1620","day":41,"season":2,"sday":11,"kind":"meet","imp":1,"text":"The Coin of Thornwall and The Thunder of Frosthold cross paths in Thornmere Ruins. Nobody draws, but nobody turns their back either.","heroes":["h1","h8","h16","h5","h3","h4","h15"],"parties":["p6","p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1634","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Brix runs the crew through shield drills at dawn. There's groaning. There's improvement.","heroes":["h1"],"parties":["p6"],"loc":"thornmere_ruins","skill":"drillmaster","wx":"storm"},{"id":"e1641","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Coin of Thornwall sets their sights for the season: to finish the season as one of the top three parties.","heroes":["h1","h8","h16"],"parties":["p6"]},{"id":"e1645","day":41,"season":2,"sday":11,"kind":"big_move","imp":4,"text":"The Coin of Thornwall slays Mother Thornmere, a Swamp Troll and a Siren at the bottom of Thornmere Ruins and lives to tell of it. On the table: Brix +141 renown (5th to 1st), Hazel +121 (8th to 3rd) and Tamsin +120 (6th to 2nd). The Coin of Thornwall +198 party renown (2nd to 1st among the crews).","heroes":["h1","h8","h16"],"parties":["p6"],"cause":"e1585","moves":[{"hero":"h1","gain":141,"from":5,"to":1},{"hero":"h8","gain":121,"from":8,"to":3},{"hero":"h16","gain":120,"from":6,"to":2}],"party_moves":[{"party":"p6","gain":198,"from":2,"to":1}],"fight":"f126"},{"id":"e1680","day":43,"season":2,"sday":13,"kind":"bounty","imp":2,"text":"The guild clerk in Carrbridge counts out bounties for The Coin of Thornwall until the cashbox is empty: 68 silver each.","heroes":["h1"],"parties":["p6"],"loc":"carrbridge","amount":68,"wx":"heat"},{"id":"e1691","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"The Carrbridge tavern's busiest night. Brix stands in the kitchen door and nobody gets a plate they didn't order. That's Hold the Doorway for you.","heroes":["h1"],"parties":["p6"],"loc":"carrbridge","skill":"hold_the_doorway","wx":"heat"},{"id":"e1702","day":43,"season":2,"sday":13,"kind":"big_move","imp":4,"text":"The whole of The Honest Toll sings \"The Coward's Jig\" at Brix. On the table: Brix +83 renown (holds 1st). The Coin of Thornwall +53 party renown (holds 1st among the crews).","heroes":["h1"],"parties":["p6"],"cause":"e1690","moves":[{"hero":"h1","gain":83,"from":1,"to":1}],"party_moves":[{"party":"p6","gain":53,"from":1,"to":1}],"song":"s30_18"},{"id":"e1710","day":44,"season":2,"sday":14,"kind":"road","imp":3,"text":"A letter of introduction, in Lady Vane's own hand and rather too much ink, is the thanks Lady Perpetua Vane gives Brix. It carries weight in the right towns.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"carrbridge~saltmarrow","traveller":"perpetua","road_rec":"r278"},{"id":"e1729","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"A herd of sheep comes round the bend. Brix plants his feet. The sheep go round.","heroes":["h1"],"parties":["p6"],"loc":"carrbridge","skill":"hold_the_doorway"},{"id":"e1843","day":47,"season":2,"sday":17,"kind":"road","imp":3,"text":"Gerald the skeleton has come apart on the road. Brix helps the students find all the bits and tie Gerald back together with bootlaces.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"saltcliffs~saltmarrow","traveller":"truant_scholars","road_rec":"r308"},{"id":"e1883","day":48,"season":2,"sday":18,"kind":"boss_race","imp":3,"text":"The Coin of Thornwall and The Tidal Ledger are headed for the same hole in the ground: The Sunken Vault, where The Kraken of the Vault waits. Somebody is going to be disappointed.","heroes":["h1","h8","h16","h7","h19","h2","h14"],"parties":["p6","p7"],"loc":"sunken_vault","wx":"fog"},{"id":"e1888","day":48,"season":2,"sday":18,"kind":"talent","imp":1,"text":"Hazel assesses the skeletons at the Sunken Vault like a jeweller with gems. Two are rubbish. One is a femur of note.","heroes":["h8"],"parties":["p6"],"loc":"sunken_vault","skill":"bone_market","wx":"fog"},{"id":"e1895","day":48,"season":2,"sday":18,"kind":"argument","imp":1,"text":"Hazel and Brix are not speaking. It's about whether the last fight was a retreat or a 'tactical repositioning'. It's never really about whether the last fight was a retreat or a 'tactical repositioning'.","heroes":["h8","h1"],"parties":["p6"]},{"id":"e1910","day":49,"season":2,"sday":19,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into the Sunken Vault, mostly unexplored (23%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e1911","day":49,"season":2,"sday":19,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of the Sunken Vault at a push pace: 2 rooms (the deposit boxes, the tellers' cages).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1912","day":49,"season":2,"sday":19,"kind":"talent","imp":1,"text":"Tamsin sings the one about the sailor and the turnip at the fire. Brix knows the harmony.","heroes":["h16","h1"],"parties":["p6"],"loc":"sunken_vault","skill":"drinking_songs","wx":"fog"},{"id":"e1921","day":50,"season":2,"sday":20,"kind":"fight","imp":3,"text":"In the guards' barracks on floor 2 of the Sunken Vault, the Coin of Thornwall is routed by 5 Drowned. Hazel was the last one out and the angriest about it. Brix has to be dragged out.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f141","foes":["drowned","drowned","drowned"],"where":"in the guards' barracks on floor 2 of the Sunken Vault","won":false,"close":true,"shape":"place","reworded":15,"wx":"fog"},{"id":"e1922","day":50,"season":2,"sday":20,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of the Sunken Vault at a steady pace: 3 rooms (the scriveners' hall, a hidden room behind the scriveners' hall, the guards' barracks).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1923","day":50,"season":2,"sday":20,"kind":"delve_done","imp":3,"text":"After 2 days and one bad fight, The Coin of Thornwall climbs out, calling it a retreat with dignity. They put 9% of it on paper, made it to floor 2, turned up the deposit boxes, the tellers' cages and a hidden room behind the scriveners' hall, cleared 4 rooms and split 180 silver on the way up. The Sunken Vault is mostly unexplored (27%) now, with the league's pencil marks all over it.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","days":2,"bottom":false,"rooms":["the deposit boxes","the tellers' cages"],"gold":180,"out":"Driven out","turn":"routed","wx":"fog"},{"id":"e1940","day":50,"season":2,"sday":20,"kind":"boss_race","imp":2,"text":"The Coin of Thornwall drops out of the race for The Kraken of the Vault. That leaves The Tidal Ledger in it.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e1945","day":50,"season":2,"sday":20,"kind":"talent","imp":2,"text":"Tamsin recognises the builder's mark at the Sunken Vault and knows where the old treasury was. It's still there, mostly.","heroes":["h16"],"parties":["p6"],"loc":"sunken_vault","skill":"local_history","wx":"fog"},{"id":"e1974","day":51,"season":2,"sday":21,"kind":"ambush","imp":2,"text":"Tamsin hits hardest as the Coin of Thornwall sees off 4 Bandits on the road to the Salt Cliffs. The bandit lost a turn to Tamsin's Stampede. Without Hazel's Raise Skeleton, this goes differently. Brix was already counting the loot before the last one fell. Loot: 21 silver each, 4 stolen goods, 5 rations.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"saltcliffs","fight":"f146","foes":["bandit","bandit","bandit"],"where":"on the road to The Salt Cliffs","won":true,"close":false,"shape":"hero","reworded":-23,"wx":"fog"},{"id":"e1976","day":51,"season":2,"sday":21,"kind":"ambush","imp":2,"text":"The Coin of Thornwall gets the better of 3 Cliff Crabs at their camp in the Salt Cliffs, in the middle of the night. The last cliff crab doesn't stay to see the end. Hazel's Raise Skeleton brought help, and the help earned its keep. Tamsin saw every rush coming and shouted it in time. Loot: 5 chitin, 3 cliff crab claws, 3 fish.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"saltcliffs","fight":"f147","foes":["crab","crab","crab"],"where":"at their camp in The Salt Cliffs, in the middle of the night","won":true,"close":false,"shape":"plain","reworded":-31,"wx":"fog"},{"id":"e1981","day":51,"season":2,"sday":21,"kind":"meet","imp":2,"text":"Ottoline and Tamsin swap stories in the Salt Cliffs while The Tidal Ledger and The Coin of Thornwall swap rumours.","heroes":["h7","h19","h2","h14","h1","h8","h16"],"parties":["p7","p6"],"loc":"saltcliffs","wx":"fog"},{"id":"e2029","day":52,"season":2,"sday":22,"kind":"campfire","imp":1,"text":"Hazel and Tamsin have shared a month of roads in The Coin of Thornwall. Ask either one about the other and settle in for a story.","heroes":["h8","h16"],"parties":["p6"],"loc":"saltmarrow","wx":"fog"},{"id":"e2087","day":54,"season":2,"sday":24,"kind":"road","imp":3,"text":"Ambrose Nimble presses a lucky die into Brix's hand. 'Never lose it,' he says, 'and never gamble with it.'","heroes":["h1","h16","h8"],"parties":["p6"],"road":"saltcliffs~sunken_vault","traveller":"nimble","road_rec":"r347"},{"id":"e2101","day":54,"season":2,"sday":24,"kind":"campfire","imp":3,"text":"Tamsin and Hazel spend an evening at the campfire trying to whistle through a blade of grass. Only Hazel manages.","heroes":["h16","h8"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e2120","day":55,"season":2,"sday":25,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into the Sunken Vault, partly explored (36%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e2121","day":55,"season":2,"sday":25,"kind":"wild_room","imp":3,"text":"A button in the Sunken Vault that says DO NOT PRESS was not pressed by The Coin of Thornwall. Sources say they think about it every night.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","room":"wild_the_button"},{"id":"e2122","day":55,"season":2,"sday":25,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a push pace: 2 rooms (the sleeping cells, the brass button).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":["wild_the_button"]}},{"id":"e2133","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Hazel picks through the old bones at the Sunken Vault for good pieces, humming. Bone Carver, cast gently, for once.","heroes":["h8"],"parties":["p6"],"loc":"sunken_vault","skill":"bone_carver"},{"id":"e2147","day":56,"season":2,"sday":26,"kind":"fight","imp":1,"text":"A Sea Serpent makes the mistake of going for the Coin of Thornwall in a drowned staircase with a brass handrail on floor 3 of the Sunken Vault. Brix's War Chant had everyone hitting harder. Loot: 1 drake scale, 12 fangs & claws.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f165","foes":["sea_serpent"],"where":"in a drowned staircase with a brass handrail on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-23},{"id":"e2148","day":56,"season":2,"sday":26,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a steady pace: 3 rooms (a drowned staircase with a brass handrail, the silted atrium, the wall of the unclaimed).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e2157","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Brix insists the ghost from last night's story lived somewhere just like the Sunken Vault. Hazel does not enjoy this. Chalk it up to Ghost Stories.","heroes":["h1","h8"],"parties":["p6"],"loc":"sunken_vault","skill":"ghost_stories"},{"id":"e2177","day":57,"season":2,"sday":27,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a steady pace: 1 room (the cracked foundation).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2178","day":57,"season":2,"sday":27,"kind":"night","imp":2,"text":"A child turns up at The Coin of Thornwall's camp on floor 3 of the Sunken Vault, announces that the Ashveil Crypts \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e2183","day":57,"season":2,"sday":27,"kind":"talent","imp":1,"text":"Hazel lifts a music box at the Sunken Vault, hears it hum a tune all by itself, and wraps it carefully. Collectors pay for that. Haunted Antiques, the guild calls it.","heroes":["h8"],"parties":["p6"],"loc":"sunken_vault","skill":"haunted_antiques"},{"id":"e2208","day":58,"season":2,"sday":28,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a steady pace: 1 room (the cracked foundation).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2209","day":58,"season":2,"sday":28,"kind":"delve_done","imp":3,"text":"The Sunken Vault hands The Coin of Thornwall back after 4 days, dusty and squinting. They got down to floor 3, worked through 5 rooms, turned up the sleeping cells and the wall of the unclaimed, split 71 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","days":4,"bottom":false,"rooms":["the sleeping cells","the wall of the unclaimed"],"gold":71,"turn":"blocked"},{"id":"e2223","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Hazel asks Brix how far down they are. Brix gives a number that is a kind lie.","heroes":["h1","h8"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e2245","day":59,"season":2,"sday":29,"kind":"meet","imp":2,"text":"Juniper's Shields run into The Coin of Thornwall on the road between the Salt Cliffs and the Sunken Vault. Stories are exchanged, most of them exaggerated.","heroes":["h10","h12","h18","h1","h8","h16"],"parties":["p4","p6"],"loc":"saltcliffs"},{"id":"e2246","day":59,"season":2,"sday":29,"kind":"journey","imp":2,"text":"On the way to the Salt Cliffs, The Coin of Thornwall catches up with The Tidal Ledger. The conversation turns to what they'd do if they retired and never recovers.","heroes":["h1","h8","h16","h7","h19","h2","h14"],"parties":["p6","p7"]},{"id":"e2283","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"Brix drills the Saltmarrow militia for an afternoon. The militia sends round a thank-you ham. Drillmaster, minus the shouting.","heroes":["h1"],"parties":["p6"],"loc":"saltmarrow","skill":"drillmaster"},{"id":"e2301","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Coin of Thornwall set out to finish the season as one of the top three parties, and the final table says they made it. XP: Brix +840 (level 18!), Hazel +800 (level 18!), Tamsin +800 (level 17!).","heroes":[],"parties":["p6"],"xp":{"h1":840,"h8":800,"h16":800}},{"id":"e2324","day":61,"season":3,"sday":1,"kind":"contract","imp":2,"text":"The watch in Ashfen is three men and a goose. The Coin of Thornwall takes the contract to defend it when the raiders come.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"ashfen","wx":"fog"},{"id":"e2349","day":61,"season":3,"sday":1,"kind":"talent","imp":1,"text":"Tamsin lets an old Ashfen fisherman tell the one about the big pike. All forty minutes of it. That's Good Listener for you.","heroes":["h16"],"parties":["p6"],"loc":"ashfen","skill":"good_listener","wx":"fog"},{"id":"e2358","day":61,"season":3,"sday":1,"kind":"argument","imp":4,"text":"Brix and Hazel have had the same argument three times now. This time Brix threw a boot. The Coin of Thornwall is splitting into camps.","heroes":["h1","h8"],"parties":["p6"]},{"id":"e2385","day":62,"season":3,"sday":2,"kind":"argument","imp":2,"text":"The Coin of Thornwall spends the evening listening to Brix and Tamsin argue about Brix's habit of humming during ambushes.","heroes":["h1","h16"],"parties":["p6"]},{"id":"e2398","day":63,"season":3,"sday":3,"kind":"vow_broken","imp":4,"text":"So much for to share every coin: The Coin of Thornwall caught Brix skimming the haul. The vow lasted 32 days.","heroes":["h1","h8","h16"],"parties":["p6"],"cause":"e1267","in_fight":"f179"},{"id":"e2399","day":63,"season":3,"sday":3,"kind":"skim","imp":3,"text":"Hazel counts the haul twice, then looks at Brix. Brix hands back 49 silver without a word.","heroes":["h8","h1"],"parties":["p6"],"loc":"kingsroad","in_fight":"f179"},{"id":"e2400","day":63,"season":3,"sday":3,"kind":"skim","imp":1,"text":"The Coin of Thornwall sits Brix down by the fire. Twice now. Nobody shouts. That's what makes it bad. One more time and they are out.","heroes":["h8","h16","h1"],"parties":["p6"],"loc":"kingsroad","in_fight":"f179"},{"id":"e2401","day":63,"season":3,"sday":3,"kind":"ambush","imp":2,"text":"Tamsin hits hardest as the Coin of Thornwall dispatches 2 Bandit Archers, 2 Bandits and the Raiders' Captain on the walls of Ashfen. Stampede went right across their line. That was Tamsin. Without Tamsin's Wild Shape, this goes differently. Widow's Kiss rang like a bell on the first blow. Four generations of wand knew the work. Loot: 33 silver each, 7 stolen goods, 3 bandit sausages.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"kingsroad","fight":"f179","foes":["bandit_captain","bandit_archer","bandit"],"where":"on the walls of Ashfen","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2403","day":63,"season":3,"sday":3,"kind":"ability","imp":2,"text":"The fight on the King's Road is barely over and Tamsin is drawing it in the dirt with a stick: who stood where, what worked, what nearly didn't. Brix and the rest learn more than the fight itself taught them.","heroes":["h16","h1"],"parties":["p6"],"loc":"kingsroad","skill":"born_teacher","sk":"Born Teacher","rule":true},{"id":"e2404","day":63,"season":3,"sday":3,"kind":"contract","imp":4,"text":"Ashfen wakes to find the raiders gone and The Coin of Thornwall asleep on the gate, still in armour. The town pays 30 each and will not hear of anyone else buying a drink.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"ashfen"},{"id":"e2422","day":64,"season":3,"sday":4,"kind":"road","imp":3,"text":"Osk audits Tamsin's pack at the roadside, item by item, and finds everything in order, to his visible disappointment.","heroes":["h16","h1","h8"],"parties":["p6"],"road":"ashfen~carrbridge","traveller":"osk","road_rec":"r423"},{"id":"e2465","day":65,"season":3,"sday":5,"kind":"talent","imp":1,"text":"Hazel reminds the Carrbridge barkeep that ale was a copper cheaper last spring. The barkeep, beaten, agrees. Hazel puts it down to Price Memory.","heroes":["h8"],"parties":["p6"],"loc":"carrbridge","skill":"price_memory"},{"id":"e2473","day":65,"season":3,"sday":5,"kind":"campfire","imp":2,"text":"Hazel slips Toast a sausage under the table. Tamsin sees, and decides Hazel is all right.","heroes":["h16","h8"],"parties":["p6"],"loc":"carrbridge"},{"id":"e2485","day":66,"season":3,"sday":6,"kind":"ambush","imp":2,"text":"It's the Bounty Hunters' Captain and Bounty Hunter against the Coin of Thornwall on the road to Ironhaven, sent for the price on Hazel's head, and it isn't close. Hazel's Bone Spear finished the fight. Raise Skeleton did more for this fight than the scoreboard shows. That was Hazel. Brix went in first, as usual. \"Good. What's it worth?\" says Brix. Loot: 23 silver each, 7 stolen goods.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"kingsroad","fight":"f194","foes":["bandit_captain","bandit"],"where":"on the road to Ironhaven, sent for the price on Hazel's head","won":true,"close":false,"shape":"foe","reworded":-13},{"id":"e2486","day":66,"season":3,"sday":6,"kind":"gift","imp":2,"text":"Hazel gets Brix's old Goblin-Stitched Fine Cloak. \"Still good,\" says Brix. It is, mostly.","heroes":["h1","h8"],"parties":["p6"],"loc":"ironhaven"},{"id":"e2520","day":67,"season":3,"sday":7,"kind":"road","imp":3,"text":"Sir Aldous Puddle and Hazel spar on the bridge for an hour. He marks the result on the board, and the horse watches without interest.","heroes":["h8","h1","h16"],"parties":["p6"],"road":"ironhaven~redcrag","traveller":"aldous","road_rec":"r440"},{"id":"e2535","day":67,"season":3,"sday":7,"kind":"meet","imp":2,"text":"Brix and Ash swap stories on the road between Ironhaven and Redcrag Hills while The Coin of Thornwall and Juniper's Shields swap rumours.","heroes":["h1","h8","h16","h10","h12","h18"],"parties":["p6","p4"],"loc":"ironhaven","wx":"rain"},{"id":"e2581","day":68,"season":3,"sday":8,"kind":"talent","imp":2,"text":"Brix teaches Tamsin to juggle two stones. Tamsin drops both, then manages, then gloats.","heroes":["h1","h16"],"parties":["p6"],"loc":"redcrag","skill":"juggler"},{"id":"e2593","day":69,"season":3,"sday":9,"kind":"fight","imp":2,"text":"The Coin of Thornwall makes it six wins running, dispatching 2 Cave Trolls and a Giant Bat in Redcrag Hills. Tamsin's Stampede caught the cave troll square. It stayed down. Tamsin kept them off everyone with Wild Shape. Loot: 16 silver each, 2 troll hide, 5 ore.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"redcrag","fight":"f201","foes":["cave_troll","cave_troll","giant_bat"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"streak","reworded":-28},{"id":"e2594","day":69,"season":3,"sday":9,"kind":"ability","imp":2,"text":"Tamsin makes the partymates replay the fight in Redcrag Hills at walking pace, like a dance lesson. Everybody feels silly. Everybody gets better.","heroes":["h16"],"parties":["p6"],"loc":"redcrag","skill":"born_teacher","sk":"Born Teacher","rule":true},{"id":"e2637","day":70,"season":3,"sday":10,"kind":"campfire","imp":1,"text":"Hazel steadies Tamsin's nerves before the descent. \"We go together. We come back together.\"","heroes":["h8","h16"],"parties":["p6"],"loc":"ironhaven"},{"id":"e2652","day":71,"season":3,"sday":11,"kind":"road","imp":4,"text":"Tamsin finds Wenna behind a proper stall at last, selling the same buttons from the same cart. She waves him to the front of the line.","heroes":["h16","h1","h8"],"parties":["p6"],"road":"ironhaven~thornwall","traveller":"wenna","road_rec":"r475"},{"id":"e2665","day":71,"season":3,"sday":11,"kind":"campfire","imp":1,"text":"Hazel and Tamsin plant a few seeds by the roadside and promise to check on them next time through.","heroes":["h8","h16"],"parties":["p6"],"loc":"ironhaven"},{"id":"e2674","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Coin of Thornwall's plan for the season, as told to the barkeep: to earn 400 silver between them before the season ends.","heroes":["h1","h8","h16"],"parties":["p6"]},{"id":"e2688","day":72,"season":3,"sday":12,"kind":"night_game","imp":2,"text":"The crew braces for a fight on the road to Thornwall, but the bandit captain only clears a flat stone and says: a round of Highway Gambit, and who is first? The bandit captain reads the final board three times, shrugs and hands Hazel Captain's Brass Button, saying it was meant to be a good one. Brix keeps a hand on the pack for the next mile, and a wary eye on the ditches.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"thornwall","night":"n150","monster_game":"bandit_captain"},{"id":"e2689","day":72,"season":3,"sday":12,"kind":"road","imp":3,"text":"Twiddle presses a small bright thing into Brix's hand from the family stock. 'A tinker's thank-you,' says Granny Kettleby. Brix has been given a trinket.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"ironhaven~thornwall","traveller":"kettleby","road_rec":"r482"},{"id":"e2707","day":73,"season":3,"sday":13,"kind":"road","imp":3,"text":"A shadow takes a bite out of the sun above the road to Carrbridge. Brix watches through a smoked bottle, and a thousand people along the way gasp together.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"carrbridge~thornwall","road_rec":"r486"},{"id":"e2855","day":77,"season":3,"sday":17,"kind":"talent","imp":1,"text":"Hazel carves a set of dice from an old bone by firelight. They roll true. Suspiciously often sixes. A small Bone Carver, cast without looking up.","heroes":["h8"],"parties":["p6"],"loc":"saltcliffs","skill":"bone_carver"},{"id":"e2908","day":78,"season":3,"sday":18,"kind":"tarot","imp":2,"text":"Nobody sleeps until Hazel has read for The Coin of Thornwall. The night before the Sunken Vault, three cards: the Four of Cups, the Six of Pentacles upside down and the Five of Pentacles. Hazel suggests a different day for anything important.","heroes":["h8","h16"],"parties":["p6"],"loc":"sunken_vault","reading":"r532"},{"id":"e2939","day":79,"season":3,"sday":19,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into the Sunken Vault, partly explored (52%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e2941","day":79,"season":3,"sday":19,"kind":"fight","imp":2,"text":"In the sluice engine room on floor 1 of the Sunken Vault, 2 Cliff Crabs, the Drowned and a Siren get in the Coin of Thornwall's way, briefly. Hazel's Bone Spear finished the fight. Loot: 4 chitin, 4 remains, 6 trinkets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f223","foes":["crab","drowned","crab"],"where":"in the sluice engine room on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-15},{"id":"e2942","day":79,"season":3,"sday":19,"kind":"fight","imp":1,"text":"Win number eight in a row: the Coin of Thornwall beats a Cliff Crab, the Drowned and a Siren in the weigh-house on floor 1 of the Sunken Vault. Stampede from Tamsin left the Drowned reeling. Loot: 2 chitin, 3 fish, 3 cliff crab claws.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f224","foes":["crab","drowned","siren"],"where":"in the weigh-house on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"streak","reworded":-27},{"id":"e2943","day":79,"season":3,"sday":19,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of the Sunken Vault at a push pace: 2 rooms (the sluice engine room, the weigh-house).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e2982","day":80,"season":3,"sday":20,"kind":"fight","imp":1,"text":"The Coin of Thornwall meets a Siren, a Sea Serpent and the Drowned in the guards' armoury on floor 2 of the Sunken Vault and makes short work of them. Tamsin's Pounce put the siren down. Brix kept everyone standing (12 healed). Loot: 1 drake scale, 12 fangs & claws, 6 trinkets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f227","foes":["siren","sea_serpent","drowned"],"where":"in the guards' armoury on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-15},{"id":"e2983","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a steady pace: 2 rooms (the guards' armoury, the cracked foundation).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2989","day":80,"season":3,"sday":20,"kind":"boss_race","imp":3,"text":"Two crews, one boss. Sunlit Quills and The Coin of Thornwall have both set out for the Sunken Vault. The taverns are taking bets.","heroes":["h11","h20","h1","h8","h16"],"parties":["p2","p6"],"loc":"sunken_vault"},{"id":"e3023","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a steady pace: 1 room (the cracked foundation).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e3024","day":81,"season":3,"sday":21,"kind":"delve_done","imp":1,"text":"After 3 days underground, The Coin of Thornwall climbs back into the open air, gulping it down like water. They worked through 3 rooms, reached floor 3, found the weigh-house and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","days":3,"bottom":false,"rooms":["the weigh-house"],"gold":0,"turn":"blocked"},{"id":"e3032","day":81,"season":3,"sday":21,"kind":"boss_race","imp":2,"text":"The Coin of Thornwall drops out of the race for The Kraken of the Vault. That leaves Sunlit Quills in it.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e3039","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"Hazel tells the crew about the oldest grave Hazel ever tended. It belonged to a dog called King. One quiet Grave Tender, and done.","heroes":["h8"],"parties":["p6"],"loc":"sunken_vault","skill":"grave_tender"},{"id":"e3044","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 19 sales, 1,334 silver changing hands. Biggest haul: Bramble, 265 silver in Carrbridge. Back up from the deep: The Thunder of Frosthold (2 days in Frostspire), The Coin of Thornwall (3 days in the Sunken Vault).","heroes":["h13","h5","h1"],"parties":["p3","p6"]},{"id":"e3079","day":82,"season":3,"sday":22,"kind":"talent","imp":2,"text":"Brix drills marching order on a quiet stretch. Tamsin finally learns which side is left. Somebody asks how. 'Drillmaster,' says Brix.","heroes":["h1","h16"],"parties":["p6"],"loc":"saltcliffs","skill":"drillmaster","wx":"storm"},{"id":"e3081","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Tamsin teaches Hazel the Dwarvish for 'please', 'thank you' and 'run'. Linguist all the way, Tamsin insists.","heroes":["h16","h8"],"parties":["p6"],"loc":"saltcliffs","skill":"linguist","wx":"storm"},{"id":"e3093","day":82,"season":3,"sday":22,"kind":"campfire","imp":1,"text":"Hazel grumbles about Brix's cooking all through supper and has seconds.","heroes":["h1","h8"],"parties":["p6"],"loc":"saltcliffs","wx":"storm"},{"id":"e3144","day":83,"season":3,"sday":23,"kind":"goal_progress","imp":2,"text":"The Coin of Thornwall is getting close: earn 400 silver between them before the season ends (304 of 400 silver).","heroes":["h1","h8","h16"],"parties":["p6"]},{"id":"e3168","day":84,"season":3,"sday":24,"kind":"argument","imp":1,"text":"Tamsin says one thing too many about who lost the map. Brix says two.","heroes":["h16","h1"],"parties":["p6"]},{"id":"e3172","day":85,"season":3,"sday":25,"kind":"road","imp":4,"text":"The Truants beg Brix to let them tag along for ever. Brix declines, and walks them back to the Academy gate. They go in grumbling and come out cheering.","heroes":["h1","h16","h8"],"parties":["p6"],"road":"saltcliffs~sunken_vault","traveller":"truant_scholars","road_rec":"r582"},{"id":"e3191","day":85,"season":3,"sday":25,"kind":"tarot","imp":2,"text":"The Coin of Thornwall sit in a ring while Hazel turns the Bog-Warped Tarot for all of them before the Sunken Vault: the Two of Swords, the Ten of Wands and the Emperor. Hazel gathers the cards up quickly.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","reading":"r590","wx":"storm"},{"id":"e3212","day":86,"season":3,"sday":26,"kind":"delve","imp":1,"text":"The Coin of Thornwall descends into the Sunken Vault, partly explored (54%).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e3214","day":86,"season":3,"sday":26,"kind":"fight","imp":2,"text":"Two Sirens, the Drowned and a Cliff Crab fall to the Coin of Thornwall in the exchange floor on floor 1 of the Sunken Vault. Hazel had the last word, and the word was Bone Spear. Ask the others what won it: Tamsin's Wild Shape. Loot: 6 trinkets, 5 barnacle oysters, 2 chitin.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f241","foes":["siren","drowned","siren"],"where":"in the exchange floor on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-2,"wx":"fog"},{"id":"e3216","day":86,"season":3,"sday":26,"kind":"fight","imp":1,"text":"With Tamsin hitting hardest, the Coin of Thornwall sees off a Cliff Crab, the Drowned and a Siren in the two-key strongroom on floor 1 of the Sunken Vault. Somewhere around Tamsin's Stampede, the other side stopped believing. Loot: 2 chitin, 2 fish, 3 cliff crab claws.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f242","foes":["crab","drowned","siren"],"where":"in the two-key strongroom on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"fog"},{"id":"e3217","day":86,"season":3,"sday":26,"kind":"ability","imp":2,"text":"On the way out of the Sunken Vault, Tamsin asks Brix what went wrong. Brix says 'nothing'. Tamsin gently disagrees, with examples, and Brix comes away a better fighter.","heroes":["h16","h1"],"parties":["p6"],"loc":"sunken_vault","skill":"born_teacher","sk":"Born Teacher","rule":true,"wx":"fog"},{"id":"e3218","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 2 of the Sunken Vault at a push pace: 2 rooms (the exchange floor, the two-key strongroom).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e3225","day":86,"season":3,"sday":26,"kind":"rescue","imp":4,"text":"RESCUE in the Sunken Vault: Brix (Griffin's hero) finds Quill (Taylor's hero) bleeding in the dark and does not walk past. 2 potions later, Quill is breathing properly.","heroes":["h1","h11","h8","h16","h20"],"parties":["p6","p2"],"loc":"sunken_vault","rescuers":["h1","h8","h16"],"wx":"fog"},{"id":"e3264","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"In the rusted keyhole door on floor 2 of the Sunken Vault, the Coin of Thornwall defeats a Sea Serpent, a Siren and the Drowned. The Drowned lost a turn to Tamsin's Stampede. Brix kept everyone standing (23 healed). Loot: 1 drake scale, 8 fangs & claws, 4 serpent fillets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f248","foes":["sea_serpent","siren","drowned"],"where":"in the rusted keyhole door on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-1,"wx":"fog"},{"id":"e3266","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"The Coin of Thornwall, in fine spirits lately, handles a Sea Serpent, the Drowned and a Siren in the tellers' cages on floor 2 of the Sunken Vault. Brix called War Chant, and the line steadied. Wild Shape, from Tamsin, at exactly the right moment. Loot: 14 fangs & claws, 6 serpent fillets, 10 trinkets.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f249","foes":["sea_serpent","drowned","siren"],"where":"in the tellers' cages on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e3267","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"The Coin of Thornwall gets the better of 2 Drowned, a Sea Serpent and a Cliff Crab in the night-chute on floor 3 of the Sunken Vault. The sea serpent took Tamsin's Pounce full on and was never the same after. Make Them Wave did more for this fight than the scoreboard shows. That was Hazel. Loot: 14 trinkets, 11 barnacle oysters, 3 drake scales.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f250","foes":["drowned","sea_serpent","drowned"],"where":"in the night-chute on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-11,"wx":"fog"},{"id":"e3268","day":87,"season":3,"sday":27,"kind":"fight","imp":1,"text":"It's 2 Cliff Crabs and the Drowned against the Coin of Thornwall in the counting-house on floor 3 of the Sunken Vault, and it isn't close. Shield Wall Shove caught two cliff crabs in one go. That was Brix. Brix was wherever the trouble was, every time. Loot: 7 chitin, 7 cliff crab claws, 6 remains.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","fight":"f251","foes":["crab","drowned","crab"],"where":"in the counting-house on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-22,"wx":"fog"},{"id":"e3269","day":87,"season":3,"sday":27,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a push pace: 5 rooms (the rusted keyhole door, the tellers' cages, the night-chute and 2 more).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":5,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":4,"close":0,"gear":["common"],"fears":4,"wild":[]},"wx":"fog"},{"id":"e3270","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"An owl lands near Tamsin's fire. They both seem to be listening for the same thing. Fox Gossip all the way, Tamsin insists.","heroes":["h16"],"parties":["p6"],"loc":"sunken_vault","skill":"fox_gossip","wx":"fog"},{"id":"e3295","day":88,"season":3,"sday":28,"kind":"delve_day","imp":1,"text":"The Coin of Thornwall works floor 3 of the Sunken Vault at a cautious pace: 1 room (the cracked foundation).","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e3296","day":88,"season":3,"sday":28,"kind":"delve_done","imp":1,"text":"The Coin of Thornwall comes out after 3 days, and the first thing anyone wants is bread. They turned up the counting-house, made it to floor 3, took 6 rooms off the map's blank side and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h1","h8","h16"],"parties":["p6"],"loc":"sunken_vault","days":3,"bottom":false,"rooms":["the counting-house"],"gold":0,"turn":"blocked","wx":"fog"},{"id":"e3297","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Hazel sews the brass button onto a coat, takes it off again, and pockets it.","heroes":["h8"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e3332","day":89,"season":3,"sday":29,"kind":"ability","imp":2,"text":"Near the Salt Cliffs Tamsin stops to hear the latest from a family of hares. Hazel waits politely. Tamsin comes away much wiser.","heroes":["h16","h8"],"parties":["p6"],"loc":"saltcliffs","skill":"fox_gossip","sk":"Fox Gossip","rule":true,"wx":"fog"},{"id":"e3372","day":90,"season":3,"sday":30,"kind":"goal_done","imp":4,"text":"The Coin of Thornwall can cross it off: earn 400 silver between them before the season ends. Drinks are on them. XP: Brix +960 (level 22!), Hazel +800, Tamsin +800.","heroes":["h1","h8","h16"],"parties":["p6"],"xp":{"h1":960,"h8":800,"h16":800}}],"roles":{"h8":"Grim one","h1":"Leader · Shield","h16":"Tracker"},"quest":{"what":"Head back to town","where":"Veldrock","why":"packs full; Veldrock pays about 217 silver more for the haul","floor":null,"floors":null},"tactics":{"front":["h1"],"back":["h8","h16"],"plan":"Brix holds the front; Hazel casts from behind; Tamsin picks off whatever gets close.","traits":{"boldness":0.33,"risk":0.36,"greed":0.14,"sociability":0.04,"honor":-0.25,"curiosity":-0.24,"temper":0.12,"loyalty":0.06},"mix":"1 blade, 1 caster, 1 bow","notes":["One shield. If Brix falls, the line goes with him.","No healer: every wound comes home with them."],"style":["bold","reckless","balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h16","id":"pounce","name":"Pounce","desc":"Clears the front rank in one bound.","tags":["beast"],"rank":3,"uses":27},{"hero":"h8","id":"bone_spear","name":"Bone Spear","desc":"Old bone, thrown with feeling.","tags":["death"],"rank":3,"uses":19},{"hero":"h16","id":"stampede","name":"Stampede","desc":"Every animal in the valley, briefly on the same side.","tags":["beast"],"rank":2,"uses":17},{"hero":"h8","id":"drain_life","name":"Drain Life","desc":"Their loss, literally your gain.","tags":["death","heal"],"rank":1,"uses":12},{"hero":"h8","id":"alchemists_fire","name":"Alchemist's Fire","desc":"A clay jar with strong opinions.","tags":["craft","fire"],"rank":1,"uses":11},{"hero":"h8","id":"chill_touch","name":"Chill Touch","desc":"A grave-cold hand on the shoulder.","tags":["death"],"rank":1,"uses":7},{"hero":"h8","id":"soul_reap","name":"Soul Reap","desc":"A scythe-sweep that drinks.","tags":["death"],"rank":1,"uses":5},{"hero":"h1","id":"shield_wall_shove","name":"Shield Wall Shove","desc":"Steps forward once, and the whole enemy line sits down.","tags":[],"rank":1,"uses":2},{"hero":"h16","id":"sic_em","name":"Sic 'Em","desc":"One word. The dog has waited all day for that word.","tags":["beast"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h1","id":"hold_the_line","name":"Hold the Line","desc":"Nobody steps back. Nobody.","tags":["guard","command"],"rank":2,"uses":33},{"hero":"h1","id":"war_chant","name":"War Chant","desc":"A song with a body count.","tags":["music","rage"],"rank":1,"uses":24},{"hero":"h16","id":"wild_shape","name":"Wild Shape","desc":"Fur, fangs, and a terrible howl.","tags":["beast","rage"],"rank":1,"uses":22},{"hero":"h1","id":"intercept","name":"Intercept","desc":"Steps in front of the blow meant for a friend.","tags":["guard"],"rank":3,"uses":9},{"hero":"h8","id":"arcane_shield","name":"Arcane Shield","desc":"A shimmer over the whole party.","tags":["arcane","guard"],"rank":1,"uses":9},{"hero":"h1","id":"bastion","name":"Bastion","desc":"Plants the shield. Everything behind it is somebody else's problem.","tags":["guard"],"rank":1,"uses":5},{"hero":"h1","id":"shield_wall","name":"Shield Wall","desc":"Plants their feet and dares anyone to try.","tags":["guard"],"rank":2,"uses":4}]},{"label":"Tricks","skills":[{"hero":"h8","id":"raise_skeleton","name":"Raise Skeleton","desc":"A friend from the floor.","tags":["death"],"rank":3,"uses":33},{"hero":"h8","id":"make_them_wave","name":"Make Them Wave","desc":"Nothing breaks a line like a friend sitting back up.","tags":[],"rank":1,"uses":23},{"hero":"h1","id":"hold_the_doorway","name":"Hold the Doorway","desc":"Picks the narrowest spot in the room and becomes it.","tags":[],"rank":1,"uses":6},{"hero":"h1","id":"iron_oath","name":"Iron Oath","desc":"One friend down. That's the quota, says the shield.","tags":["guard"],"rank":2,"uses":4},{"hero":"h8","id":"temp_agency","name":"The Temp Agency","desc":"Two pairs of hands on short contracts. Very short. Very dead.","tags":[],"rank":1,"uses":4},{"hero":"h1","id":"last_stand","name":"Last Stand","desc":"Refuses to fall.","tags":["rage"],"rank":1,"uses":3},{"hero":"h16","id":"second_wind","name":"Second Wind","desc":"Gets back up angrier.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"heart_of_the_wood","name":"Heart of the Wood","desc":"The forest isn't finished with them yet.","tags":["nature"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h1","id":"bulwark","name":"Bulwark","desc":"A wall that walks.","tags":["guard"],"rank":1,"uses":0},{"hero":"h1","id":"fortress","name":"Fortress","desc":"Siege engines have bounced off them.","tags":["guard"],"rank":3,"uses":0},{"hero":"h16","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":1,"uses":0},{"hero":"h16","id":"thick_hide","name":"Thick Hide","desc":"Mostly fur, partly leather, all grudge.","tags":["beast"],"rank":1,"uses":0},{"hero":"h16","id":"bramble_coat","name":"Bramble Coat","desc":"Hugging remains inadvisable.","tags":["nature"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h1","id":"rumourmonger","name":"Rumourmonger","desc":"Hears everything first. Repeats most of it.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h1","id":"ghost_stories","name":"Ghost Stories","desc":"Turns a dark night into a darker one, deliciously.","tags":["lore","death"],"rank":1,"uses":0},{"hero":"h1","id":"speechmaker","name":"Speechmaker","desc":"Has a speech. Has several.","tags":["command"],"rank":1,"uses":0},{"hero":"h1","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"drillmaster","name":"Drillmaster","desc":"Drills the crew at dawn. The crew hates it. The crew is better.","tags":["command"],"rank":1,"uses":0},{"hero":"h1","id":"juggler","name":"Juggler","desc":"Keeps five things in the air and the crowd's attention.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"bouncer","name":"Bouncer","desc":"Stands in doorways, professionally.","tags":["guard"],"rank":1,"uses":0},{"hero":"h8","id":"price_memory","name":"Price Memory","desc":"Never forgets what a candle cost three winters ago.","tags":["trade"],"rank":1,"uses":0},{"hero":"h8","id":"grave_tender","name":"Grave Tender","desc":"Tidies forgotten graves. The dead appreciate it.","tags":["death","holy"],"rank":1,"uses":0},{"hero":"h8","id":"bone_carver","name":"Bone Carver","desc":"Makes dice, buttons and combs from what the fight left behind.","tags":["death","craft"],"rank":1,"uses":0},{"hero":"h8","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0},{"hero":"h8","id":"bone_market","name":"Bone Market","desc":"Undertakers pay them a premium. Sometimes in advance.","tags":["death","trade"],"rank":2,"uses":0},{"hero":"h8","id":"pickpocket","name":"Pickpocket","desc":"Tavern crowds are a buffet.","tags":[],"rank":1,"uses":0},{"hero":"h8","id":"haunted_antiques","name":"Haunted Antiques","desc":"Knows which heirlooms come with a ghost, and charges extra.","tags":["death","trade"],"rank":1,"uses":0},{"hero":"h8","id":"grave_robbing","name":"Grave Robbing","desc":"Night shift at the cemetery.","tags":["death"],"rank":1,"uses":0},{"hero":"h8","id":"camp_cook","name":"Camp Cook","desc":"Makes rations taste like dinner. Party morale up.","tags":[],"rank":1,"uses":0},{"hero":"h16","id":"drinking_songs","name":"Drinking Songs","desc":"Knows every verse. Especially the forbidden ones.","tags":["music","rage"],"rank":1,"uses":0},{"hero":"h16","id":"local_history","name":"Local History","desc":"Knows who built the bridge, and who fell off it.","tags":["lore","arcane"],"rank":2,"uses":0},{"hero":"h16","id":"stargazer","name":"Stargazing","desc":"Can find north, the Swan, and the Little Ladle.","tags":["travel","lore"],"rank":1,"uses":0},{"hero":"h16","id":"hedge_wizard","name":"Hedge Wizardry","desc":"Fixes kettles with spells and spells with kettles.","tags":["arcane","craft"],"rank":1,"uses":0},{"hero":"h16","id":"good_listener","name":"Good Listener","desc":"People tell them things. Then feel better.","tags":["lore"],"rank":1,"uses":0},{"hero":"h16","id":"linguist","name":"Linguist","desc":"Speaks six languages, including Goblin, badly.","tags":["lore","arcane"],"rank":2,"uses":0},{"hero":"h16","id":"scavenger","name":"Scavenger","desc":"Checks every pocket, every boot, every crevice.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h1","dmg":322,"healed":161,"taken":210,"kills":2,"row":"front"},{"hero":"h8","dmg":2244,"healed":0,"taken":0,"kills":13,"row":"back"},{"hero":"h16","dmg":4477,"healed":0,"taken":0,"kills":20,"row":"back"}],"ground":{"name":"The Sunken Vault","fights":11}},"trophies":[{"boss":"Gruk the Warchief's Heir","monster":"goblin_warchief","place":"Goblin Camp","day":30,"season":1,"fight":"f94"},{"boss":"Mother Thornmere","monster":"hag_mother","place":"Thornmere Ruins","day":41,"season":2,"fight":"f126"}]};